const body = $input.first().json.body || $input.first().json;

// ── Retell post-call payload fields ──────────────────────────
const callId          = body.call_id || '';
const agentId         = body.agent_id || '';
const callStatus      = body.call_status || '';
const transcript      = body.transcript || '';
const recordingUrl    = body.recording_url || '';
const startTs         = body.start_timestamp || null;
const endTs           = body.end_timestamp || null;
const durationMs      = body.duration_ms || 0;
const durationMins    = durationMs ? (durationMs / 60000).toFixed(1) : '0';

// ── Post-call analysis (Retell fills these after analysis) ───
const analysis        = body.call_analysis || {};
const callSuccessful  = analysis.call_successful || false;
const summary         = analysis.custom_analysis_data?.summary || analysis.call_summary || 'No summary available';
const sentiment       = analysis.user_sentiment || 'Unknown';

// ── Dynamic variables set during call ─────────────────────────
const dynVars         = body.retell_llm_dynamic_variables || {};
const collectedVars   = body.collected_dynamic_variables || {};

const customerName    = dynVars.customer_name || collectedVars.customer_name || '';
const leadPain        = dynVars.lead_pain || collectedVars.lead_pain || '';

// ── Collected during call ─────────────────────────────────────
const collectedEmail      = collectedVars.email || '';
const bookedTime          = collectedVars.booked_time || collectedVars.booking_time || '';
const callbackTime        = collectedVars.callback_time || '';
const disqualifyReason    = collectedVars.disqualify_reason || collectedVars.disqualification_reason || '';
const decisionMaker       = collectedVars.decision_maker || 'unknown';
const teamSize            = collectedVars.team_size || '';
const toNumber            = body.to_number || '';

// ── Determine outcome ─────────────────────────────────────────
// Retell doesn't set this — we infer from collected variables + call success
let outcome = 'unknown';
if (bookedTime)                                        outcome = 'booked';
else if (callbackTime)                                 outcome = 'callback';
else if (disqualifyReason)                             outcome = 'disqualified';
else if (callStatus === 'ended' && !callSuccessful)    outcome = 'not_interested';
else if (callStatus === 'ended' && callSuccessful)     outcome = 'not_interested'; // successful call but no booking
else if (['no_answer','voicemail','busy'].includes(callStatus)) outcome = 'no_answer';

// ── Format duration ───────────────────────────────────────────
const durationLabel = durationMs
  ? `${Math.floor(durationMs/60000)}m ${Math.round((durationMs%60000)/1000)}s`
  : 'n/a';

return [{ json: {
  callId,
  agentId,
  callStatus,
  callSuccessful,
  outcome,
  customerName,
  toNumber,
  collectedEmail,
  bookedTime,
  callbackTime,
  disqualifyReason,
  decisionMaker,
  teamSize,
  leadPain,
  summary,
  sentiment,
  transcript,
  recordingUrl,
  durationLabel,
  startTs,
  endTs
}}];
